let state=null, contentPack=null, codeStart=null, codeInt=null, codeLog=[], currentCase=null;

function clone(x){return JSON.parse(JSON.stringify(x))}
function deepMerge(base, incoming){
 if(Array.isArray(base)) return Array.isArray(incoming)?incoming:base;
 if(base && typeof base==='object'){
  const out={...base};
  if(incoming && typeof incoming==='object') for(const [k,v] of Object.entries(incoming)) out[k]=k in base?deepMerge(base[k],v):v;
  return out;
 }
 return incoming===undefined?base:incoming;
}
function normalizeState(x){
 x=deepMerge(clone(seed),x||{});
 x.version=SCHEMA_VERSION;
 for(const it of x.inventory){it.qty=Number(it.qty||1);it.location=it.location||'';it.expiry=it.expiry||'';it.review=it.review||'';it.priority=it.priority||'Normal';it.custom=!!it.custom}
 for(const p of x.people||[]) p.contact=p.contact||'';
 const pn={p2:'Salomé Costa',p3:'Sara Neto',p4:'Luís Neto',p5:'João Neto',p6:'Mariana Neto'};
 (x.people||[]).forEach(p=>{if(pn[p.id])p.name=pn[p.id]});
 if((x.nodes||[]).length===3) x.nodes.forEach((n,i)=>{n.hardware='LilyGO Plus';n.band='433 MHz';n.sensor='BME280';n.antenna=n.antenna||'Antena incluída';n.status='Ativo';n.firmware=n.firmware||'';n.batteryCapacity=n.batteryCapacity||'';n.label=n.label||n.name});
 for(const r of x.research||[]){r.pico=r.pico||'';r.grade=r.grade||'';r.bias=r.bias||''}
 x.meta=x.meta||{};
 x.meta.schemaVersion=SCHEMA_VERSION;
 x.meta.lastOpened=new Date().toISOString();
 x.meta.lastBackup=x.meta.lastBackup||'';
 return x;
}
function loadState(){
 try{
  let raw=localStorage.getItem(USER_KEY), legacyKey='';
  if(!raw){for(const k of LEGACY_KEYS){raw=localStorage.getItem(k);if(raw){legacyKey=k;break}}}
  state=normalizeState(raw?JSON.parse(raw):clone(seed));
  if(legacyKey){state.meta.migratedFrom=legacyKey;localStorage.setItem(USER_KEY,JSON.stringify(state))}
  const cp=localStorage.getItem(CONTENT_KEY);
  contentPack=cp?deepMerge(clone(DEFAULT_CONTENT),JSON.parse(cp)):clone(DEFAULT_CONTENT);
 }catch(e){state=normalizeState(clone(seed));contentPack=clone(DEFAULT_CONTENT)}
}
function save(){
 state.meta=state.meta||{};state.meta.lastSaved=new Date().toISOString();
 localStorage.setItem(USER_KEY,JSON.stringify(state));
 renderHome();
}
function esc(v=''){return String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]))}
function safeUrl(v){
 try{const u=new URL(String(v||''),location.href);return (u.protocol==='http:'||u.protocol==='https:')?u.href:''}catch(e){return ''}
}
function uid(p='x'){return p+Date.now().toString(36)+Math.random().toString(36).slice(2,6)}
function toast(m){const el=document.getElementById('toast');el.textContent=m;el.classList.add('show');setTimeout(()=>el.classList.remove('show'),1600)}
function openModal(id){document.getElementById(id).classList.add('open')} function closeModal(id){document.getElementById(id).classList.remove('open')}
function go(p){const target=document.getElementById('page-'+p);if(!target)return false;document.querySelectorAll('.page.active').forEach(x=>x.classList.remove('active'));target.classList.add('active');document.querySelectorAll('.nav').forEach(x=>x.classList.toggle('active',x.dataset.page===p));document.body.style.overflow='';window.scrollTo(0,0);return true}
function subtab(group,id,btn){const page=btn.closest('.page');page.querySelectorAll('.sub').forEach(x=>x.classList.remove('active'));page.querySelectorAll('.tab').forEach(x=>x.classList.remove('active'));document.getElementById(id).classList.add('active');btn.classList.add('active');if(id==='clin-cases'&&!currentCase)newCase()}
function openClin(k){go('clinical');const b=[...document.querySelectorAll('#page-clinical .tab')].find(x=>x.getAttribute('onclick')?.includes("'clin-"+k+"'"));if(b)subtab('clinical','clin-'+k,b)}
function saveNote(k,id){state.notes[k]=document.getElementById(id).value;save();toast('Guardado')}
function renderHome(){
 const t=state.inventory.length,d=state.inventory.filter(x=>x.done).length,p=t?Math.round(d/t*100):0;
 homePrep.innerHTML=p+'% <small>'+d+'/'+t+' itens</small>';homeNotes.value=state.notes.general||'';
 homeHealth.innerHTML='OK <small>schema '+SCHEMA_VERSION+' · '+esc(contentPack?.version||'—')+'</small>';
 const alerts=[];
 const today=new Date();
 const exp=state.inventory.filter(x=>x.expiry && new Date(x.expiry)<today);
 if(exp.length) alerts.push(`${exp.length} item(ns) de emergência expirados`);
 const docs=state.vehicleDocs.filter(x=>x.exp && (new Date(x.exp)-today)/86400000<30);
 if(docs.length) alerts.push(`${docs.length} documento(s) de veículo a expirar/expirados`);
 const due=state.inventory.filter(x=>x.review && new Date(x.review)<today);
 if(due.length) alerts.push(`${due.length} item(ns) para rever`);
 homeAlerts.innerHTML=(alerts.length?alerts:['Sem alertas de manutenção registados.']).map(x=>`<div class="item"><span>${esc(x)}</span></div>`).join('');
}


