function renderGlobalSearch(){
 const q=(globalSearch.value||'').trim().toLowerCase();
 if(!q){globalResults.classList.remove('open');globalResults.innerHTML='';return}
 let hits=MODULE_INDEX.filter(x=>x[0].toLowerCase().includes(q)).map(x=>({title:x[0],sub:'Módulo',page:x[1],clin:x[2]}));
 for(const x of state.inventory.filter(x=>x.name.toLowerCase().includes(q)).slice(0,6)) hits.push({title:x.name,sub:'Emergency · '+x.category,page:'emergency'});
 for(const x of state.research.filter(x=>Object.values(x).join(' ').toLowerCase().includes(q)).slice(0,6)) hits.push({title:x.title,sub:'Research',page:'research'});
 for(const x of state.people.filter(x=>x.name.toLowerCase().includes(q))) hits.push({title:x.name,sub:'Família',page:'emergency'});
 for(const x of state.mods.filter(x=>x.name.toLowerCase().includes(q)).slice(0,4)) hits.push({title:x.name,sub:'Garage · '+x.vehicle,page:'garage'});
 hits=hits.slice(0,16);
 globalResults.innerHTML=hits.length?hits.map((h,i)=>`<button class="search-hit" onclick="openSearchHit(${i})"><div><b>${esc(h.title)}</b><span>${esc(h.sub)}</span></div></button>`).join(''):'<div class="item"><span>Sem resultados.</span></div>';
 globalResults._hits=hits;globalResults.classList.add('open');
}
function openSearchHit(i){
 const h=globalResults._hits?.[i];if(!h)return;globalResults.classList.remove('open');globalSearch.value='';
 if(h.page==='clinical'&&h.clin)openClin(h.clin);else go(h.page);
}
document.addEventListener('click',e=>{if(!e.target.closest('.globalbox'))globalResults?.classList.remove('open')});

/* PERFUSIONS */
const drugDefaults={Noradrenalina:'mcgkgmin',Adrenalina:'mcgkgmin',Dobutamina:'mcgkgmin',Dopamina:'mcgkgmin',Propofol:'mgkgh',Dexmedetomidina:'mcgkgh',Alfentanil:'mcgkgh',Remifentanil:'mcgkgmin',Rocurónio:'mcgkgmin',Insulina:'uih',Amiodarona:'mgh',Heparina:'uih'};
function baseAmount(a,u){if(u==='UI')return {v:a,type:'UI'};return {v:u==='g'?a*1e6:u==='mg'?a*1000:a,type:'mass'}}
function duLabel(u){return ({mcgkgmin:'mcg/kg/min',mcgkgh:'mcg/kg/h',mgkgh:'mg/kg/h',mcgmin:'mcg/min',mgh:'mg/h',uikgh:'UI/kg/h',uih:'UI/h'})[u]||u}
function doseToRate(){const a=+infAmount.value,v=+infVol.value,w=+infWt.value,d=+infDose.value,u=infDU.value,b=baseAmount(a,infAmountUnit.value);if(!(a>0&&v>0&&d>=0))return;let ph;if(u==='uih'){if(b.type!=='UI')return unitErr();ph=d}else if(u==='uikgh'){if(b.type!=='UI'||!(w>0))return unitErr();ph=d*w}else{if(b.type!=='mass')return unitErr();if(u.includes('kg')&&!(w>0))return unitErr();ph=u==='mcgkgmin'?d*w*60:u==='mcgkgh'?d*w:u==='mgkgh'?d*1000*w:u==='mcgmin'?d*60:d*1000}const rate=ph/(b.v/v);infRate.value=rate.toFixed(2);infResult.innerHTML=`<div class="big">${rate.toFixed(2)} mL/h</div><div class="subtext">${esc(infDrug.value)} · ${(b.v/v).toFixed(2)} ${b.type==='UI'?'UI':'mcg'}/mL · confirmar concentração/unidade.</div>`}
function rateToDose(){const a=+infAmount.value,v=+infVol.value,w=+infWt.value,r=+infRate.value,u=infDU.value,b=baseAmount(a,infAmountUnit.value);if(!(a>0&&v>0&&r>=0))return;const ph=(b.v/v)*r;let d;if(u==='uih')d=ph;else if(u==='uikgh')d=ph/w;else if(u==='mcgkgmin')d=ph/w/60;else if(u==='mcgkgh')d=ph/w;else if(u==='mgkgh')d=ph/w/1000;else if(u==='mcgmin')d=ph/60;else d=ph/1000;if(!isFinite(d))return unitErr();infDose.value=d.toFixed(4);infResult.innerHTML=`<div class="big">${d.toFixed(4)} ${duLabel(u)}</div><div class="subtext">Resultado inverso a ${r} mL/h.</div>`}
function unitErr(){infResult.innerHTML='<div class="big">Verificar unidades/peso</div><div class="subtext">UI e unidades de massa não podem ser misturadas; unidades por kg exigem peso.</div>'}
infDrug.addEventListener('change',()=>{infDU.value=drugDefaults[infDrug.value]||'mcgkgmin'});
function addPreset(){if(!preName.value||!(+preAmt.value>0)||!(+preVol.value>0))return;state.presets.unshift({id:uid('pr'),name:preName.value,amount:+preAmt.value,unit:preUnit.value,vol:+preVol.value,du:preDU.value});save();renderPresets()}
function renderPresets(){presetList.innerHTML=state.presets.length?'':'<div class="item"><span>Sem preparações guardadas.</span></div>';state.presets.forEach(x=>presetList.innerHTML+=`<div class="item"><div><strong>${esc(x.name)}</strong><br><span>${x.amount} ${x.unit} / ${x.vol} mL</span></div><div class="row"><button class="btn small" onclick="usePreset('${x.id}')">Usar</button><button class="btn small" onclick="delPreset('${x.id}')">×</button></div></div>`)}
function usePreset(id){const x=state.presets.find(p=>p.id===id);if(!x)return;infDrug.value=x.name;infAmount.value=x.amount;infAmountUnit.value=x.unit;infVol.value=x.vol;infDU.value=x.du}function delPreset(id){state.presets=state.presets.filter(x=>x.id!==id);save();renderPresets()}

/* VENT / ABG / ECG */
function pbw(sex,h){const inch=h/2.54;return sex==='male'?50+2.3*(inch-60):45.5+2.3*(inch-60)}
function acid(ph,co,hc){if(!(ph>0&&co>0&&hc>0))return '';if(ph<7.35){if(co>45&&hc<22)return'Acidose mista provável';if(co>45)return'Acidose respiratória predominante';if(hc<22)return'Acidose metabólica predominante';return'Acidemia'}if(ph>7.45){if(co<35&&hc>26)return'Alcalose mista provável';if(co<35)return'Alcalose respiratória predominante';if(hc>26)return'Alcalose metabólica predominante';return'Alcalemia'}if((co>45&&hc>26)||(co<35&&hc<22))return'Compensação/distúrbio misto possível';return'Próximo do equilíbrio'}
function analyzeVent(){
 const h=+vHeight.value,V=+vVt.value,R=+vRR.value,pe=+vPEEP.value,tpe=+vTotalPEEP.value,pp=+vPplat.value,pk=+vPpeak.value,fi=+vFiO2.value,spo=+vSpO2.value,ph=+vPH.value,co=+vCO2.value,o=+vO2.value,hc=+vHCO3.value,lac=+vLac.value;
 const passive=vPassive.checked, plateauValid=vPlateauValid.checked, mode=vMode.value;
 let P=NaN,vtkg=NaN,dp=NaN,cs=NaN,pf=NaN;const met=[],ad=[];
 if(h>0){P=pbw(vSex.value,h);met.push(['PBW',P.toFixed(1)+' kg'])}
 if(V>0&&P>0){vtkg=V/P;met.push(['Vt/PBW',vtkg.toFixed(1)+' mL/kg'])}
 if(V>0&&R>0)met.push(['Volume minuto',(V*R/1000).toFixed(1)+' L/min']);
 const effectivePEEP=tpe>0?tpe:pe;
 if(pp>0&&plateauValid&&passive){
   dp=pp-effectivePEEP;met.push(['Driving pressure',dp.toFixed(1)+' cmH₂O']);
   if(dp>0&&V>0){cs=V/dp;met.push(['Cstat',cs.toFixed(1)+' mL/cmH₂O'])}
 }else if(pp>0){met.push(['Pplat/ΔP','Interpretação limitada'])}
 if(o>0&&fi>0&&fi<=100){pf=o/(fi/100);met.push(['P/F',pf.toFixed(0)])}
 if(ph>0)met.push(['Ácido-base',acid(ph,co,hc)]);
 ventMetrics.innerHTML=met.map(x=>`<div class="item"><strong>${x[0]}</strong><span>${x[1]}</span></div>`).join('');
 if(vtkg>8)ad.push(['bad','Vt >8 mL/kg PBW','Rever estratégia protetora, sobretudo em ARDS/risco VILI.']);
 else if(vtkg>=4&&vtkg<=8)ad.push(['ok','Vt 4–8 mL/kg PBW','Faixa protetora habitual; individualizar ao contexto.']);
 if(pp>30&&plateauValid&&passive)ad.push(['bad','Pplat >30 cmH₂O','Rever Vt, PEEP, compliance e contexto, garantindo pausa inspiratória válida.']);
 if(dp>15)ad.push(['warn','Driving pressure >15','Marcador fisiológico/observacional; rever mecânica e estratégia sem usar o valor como alvo isolado.']);
 if(pk>0&&pp>0&&mode==='VC-AC'&&plateauValid&&passive&&pk-pp>10)ad.push(['warn','Ppeak−Pplat elevado em VC','Sugere componente resistiva: secreções, broncospasmo, TOT/circuito e fluxo.']);
 if(pk>0&&pp>0&&mode!=='VC-AC')ad.push(['ok','Ppeak−Pplat não interpretado como resistência','Esse gradiente depende do modo/fluxo e não é aplicado automaticamente fora de VC-AC.']);
 if(!passive||!plateauValid)ad.push(['warn','Mecânica com validade limitada','Pplat, ΔP e Cstat exigem condições de medição adequadas e ausência de esforço significativo para interpretação estática.']);
 if(tpe>pe&&tpe>0)ad.push(['warn','PEEP total > PEEP set','Auto-PEEP/intrinsic PEEP é possível; integrar curva expiratória e manobra válida.']);
 if(pf>0&&pf<100)ad.push(['bad','P/F <100','Hipoxemia muito importante; integrar definição/causa e estratégia respiratória.']);
 if(ph<7.20&&co>45)ad.push(['bad','Acidémia + hipercapnia','Rever ventilação minuto/espaço morto sem ultrapassar limites protetores.']);
 if(spo>0&&fi>=60&&spo<90)ad.push(['bad','SpO₂ baixa com FiO₂ elevada','Confirmar sinal, circuito/via aérea e deterioração aguda.']);
 if(lac>=4)ad.push(['bad','Lactato ≥4','Integrar perfusão, tendência e causas não hipóxicas.']);
 ventAdvice.innerHTML=(ad.length?ad:[['ok','Sem red flags automáticas','Rever curvas, sincronia, causa e tendência.']]).map(x=>`<div class="${x[0]==='bad'?'redflag':'advice'}"><strong>${x[1]}</strong><br>${x[2]}</div>`).join('');
 ventSummary.innerHTML=`<div class="big">${acid(ph,co,hc)||'Análise calculada'}</div><div class="subtext">${isFinite(P)?'PBW '+P.toFixed(1)+' kg · ':''}${isFinite(vtkg)?'Vt '+vtkg.toFixed(1)+' mL/kg · ':''}${isFinite(pf)?'P/F '+pf.toFixed(0):''}</div>`;
}
function analyzeECG(){const r=+eRate.value,q=+eQRS.value,pr=+ePR.value,qt=+eQTc.value,reg=eReg.value,p=eP.value,st=eST.value,sym=eSymptoms.value,le=eLeads.value;const o=[];if(sym==='yes')o.push(['bad','Instabilidade/sintomas','Priorizar ABC, monitorização e algoritmo urgente conforme quadro.']);if(reg==='Irregularmente irregular'&&p==='Ausentes/não visíveis')o.push(['ok','Compatível com FA','Confirmar traçado e contexto.']);if(r>=150&&reg==='Regular'&&q>0&&q<120)o.push(['warn','Taquicardia regular estreita','TSV possível; considerar flutter 2:1 e sinusal.']);if(r>100&&q>=120)o.push(['bad','Taquicardia de QRS largo','TV é diagnóstico crítico a assumir/excluir; estabilidade dita urgência.']);if(pr>200)o.push(['warn','PR prolongado','Compatível com BAV 1.º grau se cada P conduz.']);if(qt>=500)o.push(['bad','QTc ≥500 ms','Rever fármacos e K/Mg/Ca; risco de torsades.']);if(st==='elev'||st==='both')o.push(['bad','Elevação ST '+esc(le),'Se nova/contígua e contexto isquémico, ativar avaliação ACS urgente; considerar diferenciais.']);if(st==='dep'||st==='both')o.push(['warn','Depressão ST '+esc(le),'Pode representar isquemia/padrão recíproco.']);ecgResult.innerHTML=(o.length?o:[['ok','Sem classificação automática','Completar eixo, morfologia, ST/T e comparação prévia.']]).map(x=>`<div class="${x[0]==='bad'?'redflag':'advice'}"><strong>${x[1]}</strong><br>${x[2]}</div>`).join('')}
function loadECG(c){eSymptoms.value='no';eST.value='none';eLeads.value='';if(c==='af'){eRate.value=145;eReg.value='Irregularmente irregular';eP.value='Ausentes/não visíveis';eQRS.value=90}if(c==='svt'){eRate.value=185;eReg.value='Regular';eP.value='Ausentes/não visíveis';eQRS.value=88}if(c==='vt'){eRate.value=170;eReg.value='Regular';eP.value='Ausentes/não visíveis';eQRS.value=168;eSymptoms.value='yes'}if(c==='inf'){eRate.value=72;eReg.value='Regular';eP.value='Presentes antes de cada QRS';eQRS.value=92;eST.value='elev';eLeads.value='II, III, aVF';eSymptoms.value='yes'}analyzeECG()}
function calcHemo(){const s=+hSBP.value,d=+hDBP.value,h=+hHR.value;if(!(s>0&&d>0&&h>0))return;const m=(s+2*d)/3;hemoResult.innerHTML=`<div class="big">MAP ${m.toFixed(0)}</div><div class="subtext">Shock Index ${(h/s).toFixed(2)} · Modified ${(h/m).toFixed(2)}</div>`}function calcPF(){const p=+pfO2.value,f=+pfFi.value;if(!(p>0&&f>0))return;const x=p/(f/100);pfResult.innerHTML=`<div class="big">${x.toFixed(0)}</div><div class="subtext">P/F isolado não diagnostica ARDS.</div>`}
function analyzeABG(){const ph=+aPH.value,co=+aCO2.value,hc=+aHCO3.value,na=+aNa.value,cl=+aCl.value,al=+aAlb.value;const o=[];if(ph>0&&co>0&&hc>0)o.push(`<div class="advice"><strong>${acid(ph,co,hc)}</strong><br>pH ${ph} · PaCO₂ ${co} · HCO₃ ${hc}</div>`);if(na>0&&cl>0&&hc>0){const ag=na-cl-hc,c=isFinite(al)&&al>0?ag+2.5*(4-al):NaN;o.push(`<div class="advice"><strong>Anion gap ${ag.toFixed(1)}</strong><br>${isFinite(c)?'Corrigido '+c.toFixed(1):'Sem correção por albumina.'}</div>`);const w=1.5*hc+8;abgExtra.innerHTML=`<div class="big">Winter ${w.toFixed(1)} ±2</div><div class="subtext">${co>0?(co>w+2?'PaCO₂ acima do esperado → componente respiratório acidótico.':co<w-2?'PaCO₂ abaixo → componente alcalótico.':'Compensação aproximada esperada.'):'—'}</div>`}abgResult.innerHTML=o.join('')}
function analyzeElectrolytes(){const na=+elNa.value,k=+elK.value,ca=+elCa.value,cr=+elCr.value,o=[];if(k>=6)o.push(['bad','K⁺ ≥6,0','Hipercaliemia marcada: ECG/monitorização e protocolo urgente conforme clínica.']);else if(k>5)o.push(['warn','K⁺ elevado','Confirmar hemólise, ECG/tendência e função renal.']);else if(k>0&&k<2.5)o.push(['bad','K⁺ <2,5','Hipocaliemia marcada; risco elétrico/neuromuscular.']);else if(k>0&&k<3.5)o.push(['warn','K⁺ baixo','Rever Mg, perdas e fármacos.']);if(na>0&&(na<=120||na>=160))o.push(['bad','Disnatremia marcada','Avaliar tonicidade, sintomas, cronicidade e limites de correção.']);else if(na>0&&(na<135||na>145))o.push(['warn','Na fora da faixa habitual','Integrar volume/tonicidade/causa.']);if(ca>0&&ca<.9)o.push(['warn','Ca ionizado baixo','Integrar sintomas, QT, citrato/transfusão e Mg.']);if(cr>1.5)o.push(['warn','Creatinina elevada','Comparar baseline e diurese; valor isolado não define AKI.']);elecResult.innerHTML=(o.length?o:[['ok','Sem alertas automáticos','Usar intervalos de referência locais.']]).map(x=>`<div class="${x[0]==='bad'?'redflag':'advice'}"><strong>${x[1]}</strong><br>${x[2]}</div>`).join('')}
function calcCorrectedNa(){const n=+cnNa.value,g=+cnGlu.value,f=+cnFactor.value;if(!(n>0&&g>0))return;const c=n+f*Math.max(0,(g-100)/100);cnResult.innerHTML=`<div class="big">${c.toFixed(1)} mmol/L</div><div class="subtext">Estimativa com fator ${f}/100 mg/dL.</div>`}

/* DRUGS, SEPSIS, STROKE, SEDATION */
function renderDrugs(){const q=(drugSearch.value||'').toLowerCase(),drugSource=(contentPack.drugs&&contentPack.drugs.length?contentPack.drugs:DRUGS);drugGrid.innerHTML=drugSource.filter(d=>Object.values(d).join(' ').toLowerCase().includes(q)).map(d=>`<div class="card half"><div class="row"><h3>${esc(d.name)}</h3><div class="spacer"></div><span class="badge">${esc(d.cls)}</span></div><p><b>Uso:</b> ${esc(d.use)}</p><p style="margin-top:6px"><b>Monitor:</b> ${esc(d.monitor)}</p><div class="notice" style="margin-top:7px"><b>Riscos:</b> ${esc(d.risks)}</div></div>`).join('')}
function analyzeSepsis(){const w=+sWt.value,a=+sAge.value,m=+sMAP.value,l=+sLac.value,u=+sUrine.value,c=+sCRT.value,shock=sShock.value==='yes',o=[];if(shock&&w>0)o.push(['ok','Cristaloide inicial SSC',`30 mL/kg ≈ ${(30*w).toFixed(0)} mL nas primeiras 3 h é referência condicional; individualizar e reavaliar.`]);if(m>0&&m<60)o.push(['bad','MAP muito baixa',`MAP ${m} · referência inicial ${a>=65?'60–65':'≈65'} mmHg.`]);else if(m>0&&m<65)o.push(['warn','MAP <65',`Integrar perfusão; ${a>=65?'SSC sugere 60–65 em ≥65 anos.':'alvo inicial ≈65.'}`]);if(l>=4)o.push(['bad','Lactato ≥4','Marcador de risco; avaliar tendência/etiologia.']);else if(l>=2)o.push(['warn','Lactato elevado','Acompanhar tendência no contexto.']);if(u>0&&u<.5)o.push(['warn','Diurese <0,5 mL/kg/h','Rever perfusão/renal/obstrução.']);if(c>3)o.push(['warn','CRT prolongado','Pode apoiar avaliação periférica de perfusão.']);if(shock)o.unshift(['bad','Choque/hipoperfusão','Tratamento e ressuscitação imediatos; choque instável pode exigir fluidos+vasopressor em paralelo.']);sepsisResult.innerHTML=(o.length?o:[['ok','Sem red flags calculadas','Completar avaliação clínica.']]).map(x=>`<div class="${x[0]==='bad'?'redflag':'advice'}"><strong>${x[1]}</strong><br>${x[2]}</div>`).join('')}
function analyzeStroke(){const h=+stHours.value,n=+stNIHSS.value,s=+stSBP.value,d=+stDBP.value,b=stBleed.value,l=stLVO.value,a=stDOAC.value,o=[];if(b==='yes')o.push(['bad','Hemorragia identificada','Sair do algoritmo IVT isquémico e ativar via ICH.']);else{if(b==='unknown')o.push(['bad','Imagem pendente','TC/imagem urgente antes de decisão reperfusão.']);if(h>0&&h<=4.5)o.push(['ok','Dentro da janela padrão IVT','Elegibilidade depende de imagem, défice, PA e contraindicações.']);else if(h>4.5)o.push(['warn','>4,5 h','Seleção por imagem avançada/MT pode continuar relevante.']);if((s>=185||d>=110)&&h<=4.5)o.push(['bad','PA ≥185/110','Acima da referência ESO pré-IVT; seguir protocolo local.']);if(a==='yes')o.push(['bad','DOAC <48 h','Complexidade/contraindicação importante para IVT em guideline ESO salvo contextos específicos.']);if(l==='yes')o.push(['bad','Suspeita LVO','Acelerar angioimagem/MT; IVT elegível não deve atrasar trombectomia.']);if(n>=6)o.push(['ok','NIHSS significativo','Integrar défice incapacitante e imagem vascular.'])}strokeResult.innerHTML=o.map(x=>`<div class="${x[0]==='bad'?'redflag':'advice'}"><strong>${x[1]}</strong><br>${x[2]}</div>`).join('')||'<div class="advice">Introduz os dados.</div>'}
function updateRASS(){const m={4:'Combativo',3:'Muito agitado',2:'Agitado',1:'Inquieto',0:'Alerta e calmo','-1':'Sonolento','-2':'Sedação ligeira','-3':'Sedação moderada','-4':'Sedação profunda','-5':'Não despertável'},v=+rass.value;rassResult.innerHTML=`<div class="big">RASS ${v>0?'+':''}${v}</div><div class="subtext">${m[v]}</div>`}function calcCPOT(){const t=+c1.value+ +c2.value+ +c3.value+ +c4.value;cpotResult.innerHTML=`<div class="big">${t}/8</div><div class="subtext">${t>=3?'Dor comportamental clinicamente relevante é possível; correlacionar.':'Reavaliar em movimento/procedimento.'}</div>`}function calcBPS(){const t=+b1.value+ +b2.value+ +b3.value;bpsResult.innerHTML=`<div class="big">${t}/12</div><div class="subtext">Score mínimo 3; usar tendência/contexto.</div>`}

/* ALS / CRRT / FLUID / SCALES */
function fmt(sec){return String(Math.floor(sec/60)).padStart(2,'0')+':'+String(sec%60).padStart(2,'0')}function startCode(){if(codeStart)return;codeStart=Date.now();codeInt=setInterval(()=>codeTimer.textContent=fmt(Math.floor((Date.now()-codeStart)/1000)),1000);codeMark('Timer iniciado')}function codeMark(n){if(!codeStart){codeStart=Date.now();codeInt=setInterval(()=>codeTimer.textContent=fmt(Math.floor((Date.now()-codeStart)/1000)),1000)}const t=fmt(Math.floor((Date.now()-codeStart)/1000));codeLog.unshift({n,t});codeEvents.innerHTML=codeLog.map(x=>`<div class="item"><strong>${x.n}</strong><span>${x.t}</span></div>`).join('')}function resetCode(){clearInterval(codeInt);codeStart=null;codeInt=null;codeLog=[];codeTimer.textContent='00:00';codeEvents.innerHTML=''}
function calcCRRT(){const w=+crWt.value,d=+crD.value||0,r=+crR.value||0,u=+crU.value||0;if(!(w>0))return;const e=d+r+u;crResult.innerHTML=`<div class="big">${(e/w).toFixed(1)} mL/kg/h</div><div class="subtext">Efluente bruto ${e.toFixed(0)} mL/h · dose entregue depende de downtime/pré-diluição.</div>`}
function addFluid(){state.fluidRecords.unshift({id:uid('fl'),date:flDate.value||new Date().toISOString(),wt:+flWt.value||0,input:+flIn.value||0,output:+flOut.value||0,urine:+flUrine.value||0,hours:+flHours.value||24});save();renderFluid()}function renderFluid(){fluidTable.innerHTML='';state.fluidRecords.forEach(x=>{const bal=x.input-x.output,u=x.wt>0?x.urine/x.wt/x.hours:NaN;fluidTable.innerHTML+=`<tr><td>${new Date(x.date).toLocaleString('pt-PT')}</td><td>${x.input}</td><td>${x.output}</td><td>${bal>=0?'+':''}${bal}</td><td>${isFinite(u)?u.toFixed(2)+' mL/kg/h':x.urine}</td><td><button class="btn small" onclick="delFluid('${x.id}')">×</button></td></tr>`})}function delFluid(id){state.fluidRecords=state.fluidRecords.filter(x=>x.id!==id);save();renderFluid()}
function calcGCS(){const e=+gE.value,v=+gV.value,m=+gM.value;gResult.innerHTML=`<div class="big">${e+v+m}/15</div><div class="subtext">E${e} V${v} M${m}</div>`}
function calcCrCl(){const a=+cgAge.value,w=+cgWt.value,c=+cgCr.value;if(!(a>0&&w>0&&c>0))return;let x=(140-a)*w/(72*c);if(cgSex.value==='female')x*=.85;cgResult.innerHTML=`<div class="big">${x.toFixed(0)} mL/min</div><div class="subtext">Cockcroft-Gault; seleção de peso depende do contexto.</div>`}function calcOsm(){const n=+osNa.value,g=+osGlu.value||0,b=+osBun.value||0;if(!(n>0))return;const x=2*n+g/18+b/2.8;osResult.innerHTML=`<div class="big">${x.toFixed(1)} mOsm/kg</div>`}function calcBody(){const w=+boWt.value,h=+boHt.value;if(!(w>0&&h>0))return;const bmi=w/((h/100)**2),bsa=Math.sqrt(w*h/3600);boResult.innerHTML=`<div class="big">BMI ${bmi.toFixed(1)}</div><div class="subtext">BSA ${bsa.toFixed(2)} m² · Mosteller.</div>`}

/* CASES / CHECKLISTS / ISBAR */
const CASES=[
{title:'Choque séptico',text:'72 kg, infeção provável, MAP 54, lactato 4,6 e pele marmoreada. Prioridade?',choices:['Aguardar nova gasimetria','Ressuscitação/hemodinâmica imediata + acelerar antimicrobianos/source control','Apenas diurético','Reduzir monitorização'],correct:1,why:'SSC 2026: sépsis/choque é emergência; tratamento, hemodinâmica, antimicrobianos e source control devem ser acelerados.'},
{title:'Ventilação protetora',text:'ARDS, PBW 60 kg, Vt 540 mL, Pplat 32, PEEP 10. O que rever?',choices:['Vt ≈9 mL/kg + Pplat elevada','PEEP 10 isolada','FC desconhecida','Sexo'],correct:0,why:'Vt/PBW alto e Pplat >30 são red flags para rever estratégia.'},
{title:'AVC + LVO',text:'Défice incapacitante, 2 h, TC sem hemorragia e suspeita LVO. Circuito?',choices:['Esperar 24 h','Acelerar angioimagem/reperfusão; IVT elegível não deve atrasar MT','PA <120 sempre','Alta'],correct:1,why:'LVO deve acelerar trombectomia; IVT elegível não deve atrasar MT.'},
{title:'QRS largo',text:'FC 175 regular, QRS 170 ms, hipotensão e alteração consciência.',choices:['TSV benigna','TV crítica até prova em contrário e instabilidade determina urgência','FA lenta','Repetir ECG amanhã'],correct:1,why:'Taquicardia de QRS largo + instabilidade exige abordagem urgente.'},
{title:'Hipercaliemia',text:'K 6,7 em subida + QRS a alargar.',choices:['Sem urgência','ECG/monitorização + protocolo urgente de estabilização/deslocação/remoção conforme causa','Água oral','Suspender ECG'],correct:1,why:'Hipercaliemia marcada com alteração elétrica é emergência.'}
];
function newCase(){const caseSource=(contentPack.cases&&contentPack.cases.length?contentPack.cases:CASES);currentCase=caseSource[Math.floor(Math.random()*caseSource.length)];caseArea.innerHTML=`<div class="advice"><strong>${esc(currentCase.title)}</strong><br>${esc(currentCase.text)}</div><div class="stack">${currentCase.choices.map((c,i)=>`<button class="casechoice" onclick="answerCase(${i},this)">${String.fromCharCode(65+i)}. ${esc(c)}</button>`).join('')}</div><div id="caseFeedback"></div>`}function answerCase(i,b){if(b.dataset.done)return;document.querySelectorAll('.casechoice').forEach(x=>x.dataset.done='1');state.caseStats.total++;if(i===currentCase.correct){state.caseStats.correct++;b.classList.add('correct')}else{b.classList.add('wrong');document.querySelectorAll('.casechoice')[currentCase.correct].classList.add('correct')}caseFeedback.innerHTML=`<div class="advice"><strong>Feedback</strong><br>${esc(currentCase.why)}</div>`;save();updateCaseScore()}function updateCaseScore(){caseScore.textContent=state.caseStats.correct+'/'+state.caseStats.total}function resetCase(){state.caseStats={correct:0,total:0};save();updateCaseScore();newCase()}
const CHECKS={icu:[['Identificação/motivo','Diagnóstico e objetivos imediatos'],['ABCDE','Neurológico, perfusão, ventilação'],['Via aérea/TOT/cuff','Posição, fixação e plano'],['Ventilador/GSA','Modo, Vt/PBW, PEEP, FiO₂, pressões'],['Acessos/dispositivos','CVC, arterial, drenos, SNG, algália'],['Perfusões alto risco','Fármaco, concentração, dose, via'],['Sedação/dor/delirium','RASS, CPOT/BPS, objetivo'],['Pele/prevenção','Pressão, mobilização, dispositivos'],['Balanço/renal','Diurese, creatinina, TSR'],['Família/comunicação','Contacto, informação e plano'],['Profilaxias/segurança','VTE, alergias, isolamento'],['Plano/pendentes','Prioridades, exames, escalada']],transport:[['Identificação/destino/equipa','Confirmar doente e objetivo'],['Via aérea segura','Fixação, cuff, aspiração, plano'],['Oxigénio','Autonomia com margem'],['Ventilador transporte','Parâmetros e bateria'],['Monitorização','ECG, SpO₂, PA, capnografia se indicada'],['Acessos/perfusões','Fixação, volumes, bombas'],['Fármacos emergência','Conforme risco/protocolo'],['Drenos/linhas','Fixação e coletores'],['Documentação','Pedido/resultados'],['ISBAR','Plano de deterioração e responsabilidades']]};
function renderChecks(){const checklistSource=contentPack.checklists||CHECKS;for(const type of ['icu','transport']){const root=document.getElementById(type==='icu'?'icuChecklist':'transportChecklist');root.innerHTML=checklistSource[type].map((x,i)=>`<label class="check"><input type="checkbox" ${state.checklistState[type][i]?'checked':''} onchange="toggleCheck('${type}',${i},this.checked)"><div><strong>${x[0]}</strong><span>${x[1]}</span></div></label>`).join('')}}function toggleCheck(t,i,v){state.checklistState[t][i]=v;save()}function resetChecklist(t){state.checklistState[t]={};save();renderChecks()}
function generateISBAR(){isbarOut.textContent=`I — IDENTIFICAÇÃO\n${iI.value}\n\nS — SITUAÇÃO\n${iS.value}\n\nB — BACKGROUND\n${iB.value}\n\nA — ASSESSMENT\n${iA.value}\n\nR — RECOMMENDATION\n${iR.value}`}function copyISBAR(){navigator.clipboard?.writeText(isbarOut.textContent).then(()=>toast('ISBAR copiado'))}

/* EMERGENCY */
function renderEmergency(){renderInventory();renderPeople();renderLocations();scLoc.innerHTML=state.locations.map(x=>`<option>${esc(x.name)}</option>`).join('');emNotes.value=state.notes.emergency||''}
function renderInventory(){
 const cats=[...new Set(state.inventory.map(x=>x.category))].sort(),previousCat=invCat.value;
 invCat.innerHTML='<option value="">Todas categorias</option>'+cats.map(c=>`<option>${esc(c)}</option>`).join('');
 if(cats.includes(previousCat))invCat.value=previousCat;
 const q=(invSearch.value||'').toLowerCase(),cat=invCat.value,today=new Date();
 const a=state.inventory.filter(x=>(!cat||x.category===cat)&&(!q||x.name.toLowerCase().includes(q)));
 inventoryGrid.innerHTML=a.map(x=>{
   const expired=x.expiry&&new Date(x.expiry)<today, review=x.review&&new Date(x.review)<today;
   return `<div class="card"><div class="row"><input type="checkbox" style="width:18px" ${x.done?'checked':''} onchange="toggleInv('${x.id}',this.checked)"><div><h3>${esc(x.name)}</h3><p>${esc(x.category)}</p></div><div class="spacer"></div>${expired?'<span class="badge bad">Expirado</span>':review?'<span class="badge warn">Rever</span>':''}</div>
   <div class="form2" style="margin-top:7px"><label>Qtd<input type="number" value="${x.qty}" onchange="updateInv('${x.id}','qty',this.value)"></label><label>Local<input value="${esc(x.location||'')}" onchange="updateInv('${x.id}','location',this.value)"></label><label>Validade<input type="date" value="${esc(x.expiry||'')}" onchange="updateInv('${x.id}','expiry',this.value)"></label><label>Rever em<input type="date" value="${esc(x.review||'')}" onchange="updateInv('${x.id}','review',this.value)"></label></div>${x.custom?`<div class="actions"><button class="btn small" onclick="deleteCustomInventory('${x.id}')">Remover item personalizado</button></div>`:''}</div>`
 }).join('');
 const d=state.inventory.filter(x=>x.done).length,t=state.inventory.length,p=t?Math.round(d/t*100):0;
 invCount.textContent=a.length+' visíveis';prepBadge.textContent=p+'% · '+d+'/'+t;homePrep.innerHTML=p+'% <small>'+d+'/'+t+' itens</small>';
}
function addCustomInventory(){
 if(!ciName.value.trim()||!ciCat.value.trim())return toast('Nome e categoria são obrigatórios');
 state.inventory.push({id:uid('inv'),name:ciName.value.trim(),category:ciCat.value.trim(),qty:+ciQty.value||1,location:ciLoc.value.trim(),done:false,expiry:ciExpiry.value,review:ciReview.value,priority:ciPriority.value,custom:true});
 save();closeModal('inventoryModal');renderInventory();toast('Item adicionado');
}
function deleteCustomInventory(id){state.inventory=state.inventory.filter(x=>x.id!==id);save();renderInventory()}
function exportInventoryCSV(){
 const cols=['name','category','qty','location','done','expiry','review','priority'];
 dl([cols.join(';'),...state.inventory.map(x=>cols.map(c=>'"'+String(x[c]??'').replace(/"/g,'""')+'"').join(';'))].join('\\n'),'emergency-inventory.csv','text/csv;charset=utf-8')
}
function toggleInv(id,v){state.inventory.find(x=>x.id===id).done=v;save();renderInventory()}function updateInv(id,k,v){const x=state.inventory.find(x=>x.id===id);x[k]=k==='qty'?+v:v;save()}
function renderPeople(){peopleList.innerHTML=state.people.map(x=>`<div class="item"><div><strong>${esc(x.name)}</strong><br><span>${esc(x.role)} · ${esc(x.location)}</span></div><input style="max-width:170px" placeholder="Contacto" value="${esc(x.contact||'')}" onchange="setPersonContact('${x.id}',this.value)"></div>`).join('')}function setPersonContact(id,v){state.people.find(x=>x.id===id).contact=v;save()}
function renderLocations(){locationList.innerHTML=state.locations.map(x=>`<div class="item"><div><strong>${esc(x.name)}</strong><br><span>${esc(x.type)}</span></div><input style="max-width:210px" placeholder="Ponto encontro" value="${esc(x.meet||'')}" onchange="setMeet('${x.id}',this.value)"></div>`).join('')}function setMeet(id,v){state.locations.find(x=>x.id===id).meet=v;save()}
function generateScenario(){const t=scType.value,l=scLoc.value,c=scComms.value,i=scInjury.value;const steps=[];if(i==='yes')steps.push('ABCDE e controlo de ameaças imediatas antes de deslocação.');if(t==='Sismo')steps.push('Proteção imediata durante o abalo; após cessar, avaliar estrutura/gás/eletricidade e saídas.');if(t==='Blackout')steps.push('Confirmar extensão da falha; preservar bateria, iluminação e água; evitar elevadores.');if(t.includes('Incêndio'))steps.push('Evacuar por rota segura sem elevadores; afastar-se de fumo e seguir autoridades.');if(t==='Inundação')steps.push('Evitar pisos baixos/água em movimento; desligar energia apenas se seguro.');steps.push(`Local: ${l}. Confirmar ponto de encontro e estado dos familiares.`);steps.push(c==='yes'?'Usar telemóvel/Meshtastic com mensagens curtas e estado/local.':'Ativar plano sem rede: ponto de encontro + horários de tentativa + mensageiro físico se seguro.');scenarioOut.innerHTML=steps.map((x,n)=>`<div class="advice"><strong>${n+1}</strong> · ${esc(x)}</div>`).join('')}

/* COMMS */
function renderComms(){renderNodes();renderTelemetry();renderTests()}
function renderNodes(){
 nodeList.innerHTML=state.nodes.map(n=>`<div class="card"><div class="row"><h3>${esc(n.name)}</h3><div class="spacer"></div><span class="badge good">${esc(n.status)}</span></div><p>${esc(n.hardware)} · ${esc(n.band)} · ${esc(n.sensor)}</p>
 <div class="form2" style="margin-top:8px"><label>Etiqueta<input value="${esc(n.label||n.name)}" onchange="setNode('${n.id}','label',this.value)"></label><label>Local<input value="${esc(n.location)}" onchange="setNode('${n.id}','location',this.value)"></label><label>Firmware<input value="${esc(n.firmware||'')}" onchange="setNode('${n.id}','firmware',this.value)"></label><label>Bateria mAh<input type="number" value="${esc(n.batteryCapacity||'')}" onchange="setNode('${n.id}','batteryCapacity',this.value)"></label></div>
 <div class="list"><div class="item"><span>Antena</span><strong>${esc(n.antenna)}</strong></div></div></div>`).join('')
}
function setNode(id,k,v){const n=state.nodes.find(x=>x.id===id);if(!n)return;n[k]=k==='batteryCapacity'?Number(v)||'':v;save()}
function exportCommsCSV(){
 const rows=['type;date;node/from;to;temp;humidity;pressure;battery;rssi;snr;result'];
 for(const x of state.telemetry)rows.push(`telemetry;"${x.date}";"${x.node}";;${x.temp};${x.hum};${x.press};${x.bat};;;`);
 for(const x of state.commsTests)rows.push(`test;"${x.date}";"${String(x.from).replace(/"/g,'""')}";"${String(x.to).replace(/"/g,'""')}";;;;;${x.rssi};${x.snr};"${x.result}"`);
 dl(rows.join('\\n'),'meshtastic-logs.csv','text/csv;charset=utf-8')
}
function nullableNumber(v){return String(v).trim()===''?null:Number(v)}
function addTelemetry(){state.telemetry.unshift({id:uid('te'),node:envNode.value,date:envDate.value||new Date().toISOString(),temp:nullableNumber(envTemp.value),hum:nullableNumber(envHum.value),press:nullableNumber(envPress.value),bat:nullableNumber(envBat.value)});save();renderTelemetry()}function renderTelemetry(){teleTable.innerHTML='';state.telemetry.forEach(x=>teleTable.innerHTML+=`<tr><td>${new Date(x.date).toLocaleString('pt-PT')}</td><td>${x.node}</td><td>${x.temp!==null&&isFinite(x.temp)?x.temp:'—'}</td><td>${x.hum!==null&&isFinite(x.hum)?x.hum:'—'}</td><td>${x.press!==null&&isFinite(x.press)?x.press:'—'}</td><td>${x.bat!==null&&isFinite(x.bat)?x.bat:'—'}</td><td><button class="btn small" onclick="delTele('${x.id}')">×</button></td></tr>`);teleLatest.innerHTML=['NODE-01','NODE-02','NODE-03'].map(n=>{const x=state.telemetry.find(t=>t.node===n);return `<div class="tele"><span>${n}</span><b>${x&&x.temp!==null&&isFinite(x.temp)?x.temp+' °C':'—'}</b><span>${x&&x.hum!==null&&isFinite(x.hum)?x.hum+'% · ':''}${x&&x.press!==null&&isFinite(x.press)?x.press+' hPa':''}</span></div>`}).join('')}function delTele(id){state.telemetry=state.telemetry.filter(x=>x.id!==id);save();renderTelemetry()}
function calcFSPL(){const d=+rfDist.value,f=+rfFreq.value;if(!(d>0&&f>0))return;const p=32.44+20*Math.log10(d)+20*Math.log10(f);rfPL.value=p.toFixed(1);rfResult.innerHTML=`<div class="big">${p.toFixed(1)} dB</div><div class="subtext">Free-space only.</div>`}function calcLink(){const rx=+rfTx.value+ +rfGT.value+ +rfGR.value- +rfLoss.value- +rfPL.value,m=rx- +rfSens.value;linkResult.innerHTML=`<div class="big">${rx.toFixed(1)} dBm</div><div class="subtext">Margem teórica ${m.toFixed(1)} dB.</div>`}
function addTest(){state.commsTests.unshift({id:uid('ct'),date:new Date().toISOString(),from:tFrom.value,to:tTo.value,rssi:+tRSSI.value,snr:+tSNR.value,result:tRes.value});save();renderTests()}function renderTests(){testList.innerHTML=state.commsTests.length?'':'<div class="item"><span>Sem testes.</span></div>';state.commsTests.forEach(x=>testList.innerHTML+=`<div class="item"><div><strong>${esc(x.from)} → ${esc(x.to)}</strong><br><span>${new Date(x.date).toLocaleString('pt-PT')} · RSSI ${x.rssi} · SNR ${x.snr}</span></div><span class="badge">${x.result}</span></div>`)}

